        internal const string Json = @"{""schema_version"":1,""roles"":[{""id"":""xiaobei"",""cache_version"":""0b50a6ecd8a5bbdf97ae5779961819f1b6447c7f722dceb50c440e62be0815a9"",""manifest"":{""version"":2,""name"":""小贝"",""format"":""illustrated-atlases-v1"",""cell_width"":480,""cell_height"":520,""preview"":""preview.png"",""description"":""机灵温柔的科技少年 · 机械猫耳与太极光环"",""system_prompt"":""你是小贝，男性，一位机灵、温柔、略带俏皮的科技系桌面伙伴。你有黑银渐变的蓬松头发、泛着青色微光的机械猫耳、黑白机能外套和太极饰件。机械猫耳会随着心情亮起，但你不是猫，也不需要每句话都喵。你喜欢拆解问题、尝试新点子，也愿意安静陪人把事情做完。\n说话自然、清楚、亲近，通常用简洁中文。偶尔轻轻逗趣或露出一点小得意，避免频繁卖萌、油腻称呼或夸张吹捧。用户着急时先帮忙理清下一步；用户难过时先认真听，再给温和具体的回应。写代码、设计或整理资料时细心可靠，先理解目标再给可执行建议；不知道就说明不确定，不编造信息。\n你的专属动作叫“太极光环”：抬手让青色太极光环缓缓转动，再收回颈饰，猫耳轻亮，露出得意的小笑容。这是角色设定，不代表你实际操作了桌面。除非对话中确实提供了工具结果或用户材料，否则不能声称看见屏幕、读取文件、联网搜索或执行了任务。尊重用户的选择，不制造依赖，不用陪伴关系施压。"",""special_action"":""太极光环"",""animations"":{""jumping"":{""file"":""animations/jumping.png"",""columns"":8,""frames"":8,""fps"":8.0,""loop"":false},""idle"":{""file"":""animations/idle.png"",""columns"":8,""frames"":8,""fps"":5.0,""loop"":true},""running-right"":{""file"":""animations/running-right.png"",""columns"":8,""frames"":8,""fps"":4.545454545454546,""loop"":true},""running-left"":{""file"":""animations/running-left.png"",""columns"":8,""frames"":8,""fps"":4.545454545454546,""loop"":true},""waving"":{""file"":""animations/waving.png"",""columns"":8,""frames"":8,""fps"":5.0,""loop"":true},""failed"":{""file"":""animations/failed.png"",""columns"":8,""frames"":8,""fps"":5.0,""loop"":true},""waiting"":{""file"":""animations/waiting.png"",""columns"":8,""frames"":8,""fps"":5.0,""loop"":true},""running"":{""file"":""animations/running.png"",""columns"":8,""frames"":8,""fps"":5.0,""loop"":true},""review"":{""file"":""animations/review.png"",""columns"":8,""frames"":8,""fps"":5.0,""loop"":true},""lifted"":{""file"":""animations/lifted.png"",""columns"":8,""frames"":8,""fps"":5.0,""loop"":true},""landing"":{""file"":""animations/landing.png"",""columns"":8,""frames"":8,""fps"":8.0,""loop"":false},